{
  "states": [
    "REQUEST",
    "PARTOPEN",
    "RESPOND",
    "OPEN",
    "TIMEWAIT",
    "CLOSING"
  ],
  "transitions": [
    {
      "from": "REQUEST",
      "event": "Response",
      "action": "S.state := PARTOPEN; Set PARTOPEN timer",
      "to": "PARTOPEN"
    },
    {
      "from": "RESPOND",
      "event": "Request",
      "action": "Send Response, possibly containing Init Cookie; Destroy S and return",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "",
      "action": "S.OSR := P.seqno; S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "Response",
      "action": "Send Ack",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "",
      "action": "S.OSR := P.seqno; S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "TIMEWAIT",
      "event": "Reset",
      "action": "Tear down connection; S.state := TIMEWAIT; Set TIMEWAIT timer",
      "to": "TIMEWAIT"
    },
    {
      "from": "CLOSING",
      "event": "CloseReq",
      "action": "Generate Close; S.state := CLOSING; Set CLOSING timer",
      "to": "CLOSING"
    }
  ]
}

